82: export const fhirService = {
83:   async getDischargeSummary(patientId?: string) {
84:     try {
85:       const url = new URL('/openmrs/ws/fhir2/R4/Composition', window.location.origin);
86:       url.searchParams.append('type', 'discharge-summary');
87:       if (patientId) {
88:         url.searchParams.append('subject', `Patient/${patientId}`);
89:       }
90: 
91:       const response = await fetch(url.toString(), {
92:         headers: {
93:           'Accept': 'application/json',
94:           'Cache-Control': 'no-cache, no-store, must-revalidate',
95:           'Pragma': 'no-cache'
96:         },
97:         credentials: 'include'
98:       });
99: 
100:       return handleResponse(response);
101:     } catch (error) {
102:       console.error('Error in getDischargeSummary:', error);
103:       throw error instanceof Error ? error : new Error('Failed to fetch discharge summary');
104:     }
105:   },
106: 
107:   async createDischargeSummary(data: DischargeSummaryType) {
108:     try {
109:       // Create a Bundle containing the Composition and referenced resources
110:       const bundle = createBundle(data);
111: 
112:       const response = await fetch('/openmrs/ws/fhir2/R4/Bundle', {
113:         method: 'POST',
114:         headers: {
115:           'Content-Type': 'application/json',
116:           'Accept': 'application/json',
117:           'Cache-Control': 'no-cache, no-store, must-revalidate',
118:           'Pragma': 'no-cache'
119:         },
120:         credentials: 'include',
121:         body: JSON.stringify(bundle)
122:       });
123: 
124:       return handleResponse(response);
125:     } catch (error) {
126:       console.error('Error in createDischargeSummary:', error);
127:       throw error instanceof Error ? error : new Error('Failed to create discharge summary');
128:     }
129:   },
130: 
131:   async updateDischargeSummary(id: string, data: DischargeSummaryType) {
132:     try {
133:       // Create a Bundle containing the updated Composition and referenced resources
134:       const bundle = createBundle(data);
135: 
136:       const response = await fetch(`/openmrs/ws/fhir2/R4/Bundle/${id}`, {
137:         method: 'PUT',
138:         headers: {
139:           'Content-Type': 'application/json',
140:           'Accept': 'application/json',
141:           'Cache-Control': 'no-cache, no-store, must-revalidate',
142:           'Pragma': 'no-cache'
143:         },
144:         credentials: 'include',
145:         body: JSON.stringify(bundle)
146:       });
147: 
148:       return handleResponse(response);
149:     } catch (error) {
150:       console.error('Error in updateDischargeSummary:', error);
151:       throw error instanceof Error ? error : new Error('Failed to update discharge summary');
152:     }
153:   },
154: 
155:   async getIPDVisitDetails(patientId: string): Promise<IPDVisitDetails> {
156:     try {
157:       const url = new URL('/openmrs/ws/fhir2/R4/Bundle', window.location.origin);
158:       url.searchParams.append('_query', 'ip-care');
159:       url.searchParams.append('_filter', 'current-visit');
160:       url.searchParams.append('patient', patientId);
161: 
162:       const response = await fetch(url.toString(), {
163:         headers: {
164:           'Accept': 'application/json',
165:           'Cache-Control': 'no-cache, no-store, must-revalidate',
166:           'Pragma': 'no-cache'
167:         },
168:         credentials: 'include'
169:       });
170: 
171:       const data = await handleResponse(response);
172:       
173:       // Ensure the response matches our expected Bundle structure
174:       if (data.resourceType !== 'Bundle' || !Array.isArray(data.entry)) {
175:         throw new Error('Invalid response format from server');
176:       }
177: 
178:       return {
179:         resourceType: 'Bundle',
180:         type: 'collection',
181:         entry: data.entry
182:       };
183:     } catch (error) {
184:       console.error('Error in getIPDVisitDetails:', error);
185:       throw error instanceof Error ? error : new Error('Failed to fetch IPD visit details');
186:     }
187:   }
188: };

